FROM t_service s
LEFT JOIN t_category c ON c.id = s.category_id


        AND s.category_id = #{categoryId}


        AND s.name LIKE CONCAT('%', #{keyword}, '%')


        AND s.status = #{status}


ORDER BY s.sales DESC, s.id DESC
LIMIT #{offset}, #{size}

